from pathlib import Path
import re

root = Path("source/Hadota-WiFi-Manager-Android")
main = root / "app/src/main/java/com/hadota/wifimanager/MainActivity.java"
s = main.read_text()
old = """view.evaluateJavascript("(function(){if(document.getElementById('hadotaCaptureBtn'))return;var b=document.createElement('button');b.id='hadotaCaptureBtn';b.textContent='استيراد الأجهزة إلى Hadota';b.style='position:fixed;z-index:2147483647;top:8px;left:8px;padding:13px 16px;background:#d9b36a;color:#17120a;border:2px solid #fff;border-radius:12px;font-weight:bold;font-size:16px;box-shadow:0 2px 12px #000';b.onclick=function(){location.href='hadota://capture'};document.body.appendChild(b);})();", null);"""
new = """view.evaluateJavascript("(function(){if(document.getElementById('hadotaCaptureBtn'))return;var css='position:fixed;z-index:2147483647;top:8px;padding:11px 13px;background:#d9b36a;color:#17120a;border:2px solid #fff;border-radius:12px;font-weight:bold;font-size:14px;box-shadow:0 2px 12px #000';var b=document.createElement('button');b.id='hadotaCaptureBtn';b.textContent='استيراد الأجهزة';b.style=css+';left:8px';b.onclick=function(){location.href='hadota://capture'};document.body.appendChild(b);var q=document.createElement('button');q.id='hadotaPageInfoBtn';q.textContent='معلومات الصفحة';q.style=css+';left:155px';q.onclick=function(){var clean=function(x){return (x||'').replace(/\\\\s+/g,' ').trim()};var data={title:document.title,url:location.href,headings:Array.from(document.querySelectorAll('h1,h2,h3')).map(x=>clean(x.innerText)),tables:Array.from(document.querySelectorAll('table')).map(t=>Array.from(t.querySelectorAll('tr')).map(r=>Array.from(r.querySelectorAll('th,td')).map(c=>clean(c.innerText)))),links:Array.from(document.querySelectorAll('a')).map(a=>({text:clean(a.innerText),url:a.href})).filter(x=>x.text||x.url),fields:Array.from(document.querySelectorAll('input,select,textarea')).map(e=>({type:e.type||e.tagName.toLowerCase(),name:e.name||e.id||'',label:clean((e.labels&&Array.from(e.labels).map(l=>l.innerText).join(' '))||e.getAttribute('aria-label')||e.placeholder||''),value:(e.type==='password'||e.type==='hidden')?'[محجوب]':(e.value||'')})),buttons:Array.from(document.querySelectorAll('button,input[type=button],input[type=submit]')).map(x=>clean(x.innerText||x.value)),text:document.body?document.body.innerText:''};var shade=document.getElementById('hadotaPageInfoShade');if(shade)shade.remove();shade=document.createElement('div');shade.id='hadotaPageInfoShade';shade.style='position:fixed;inset:0;z-index:2147483647;background:#000b;padding:12px;display:flex;align-items:center;justify-content:center';var box=document.createElement('div');box.style='background:#fff;color:#171717;width:100%;max-width:720px;max-height:88vh;overflow:auto;border-radius:14px;padding:14px;direction:rtl;font:14px Arial';var head=document.createElement('div');head.style='display:flex;justify-content:space-between;align-items:center;gap:8px';var title=document.createElement('b');title.textContent='معلومات صفحة الراوتر — قراءة فقط';var close=document.createElement('button');close.textContent='إغلاق';close.onclick=function(){shade.remove()};head.append(title,close);var pre=document.createElement('pre');pre.style='white-space:pre-wrap;overflow-wrap:anywhere;direction:ltr;text-align:left;background:#f2f2f2;padding:10px;border-radius:8px;font-size:11px';pre.textContent=JSON.stringify(data,null,2);var copy=document.createElement('button');copy.textContent='نسخ كل المعلومات';copy.style='padding:12px;margin-top:8px';copy.onclick=function(){var t=JSON.stringify(data,null,2);if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(function(){copy.textContent='تم النسخ'});else{var a=document.createElement('textarea');a.value=t;box.appendChild(a);a.select();document.execCommand('copy');a.remove();copy.textContent='تم النسخ'}};box.append(head,copy,pre);shade.appendChild(box);document.body.appendChild(shade)};document.body.appendChild(q);})();", null);"""
if old not in s:
    raise SystemExit("toolbar anchor not found")
s=s.replace(old,new,1)
main.write_text(s)
gradle=root/"app/build.gradle"
g=gradle.read_text()
g=re.sub(r"versionCode\s+\d+","versionCode 24",g,count=1)
g=re.sub(r"versionName\s+'[^']+'","versionName '1.7.4'",g,count=1)
